	push	xix                                   ; F9873A  push XIX
	push	xiy                                   ; F9873B  push XIY
	push	xhl                                   ; F9873C  push XHL
	pushw	bc                                   ; F9873D  push BC
	sll	a, 2                                   ; F9873E  sll 0x02,A
	ld	c, a                                    ; F98741  ld C,A
	extz	wa                                    ; F98743  extz WA
	add	wa, 0x13C                              ; F98745  add WA,0x013c
	ld	iy, wa                                  ; F98749  ld IY,WA
	extz	xiy                                   ; F9874B  extz XIY
	push	sr                                    ; F9874D  push SR
	ei	6                                       ; F9874E  ei 0x06
	extpfx3 0x9D, 0x00, 0x24                   ; F98750  ld IX,(XIY+0x00)
	cp	ix, iy                                  ; F98753  cp IX,IY
	jr nz, MsgQueue_Send_NoDispatch__wake      ; F98755  jr NZ,0xf987a9
