	stiw_da	(0xE85554), 85                 ; FC8974  ld (0xe85554),0x0055
	extpfx4 0xB3, 0x02, 0xA0, 0x00         ; FC897B  ld (XHL),0x00a0   [llvm-mc cannot encode this]
	ld	(xiy), wa                           ; FC897F  ld (XIY),WA
