	ld	xbc, (xiz+12)                           ; FCA053  ld XBC,(XIZ+0x0c)
	push	xbc                                   ; FCA056  push XBC
	ld	xbc, (xiz+8)                            ; FCA057  ld XBC,(XIZ+0x08)
	push	xbc                                   ; FCA05A  push XBC
	lda	xiy, (xiz-16)                          ; FCA05B  lda XIY,XIZ+0xf0
